186	    /**
187	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
188	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
189	     *
190	     * @param a the first value, possibly {@code null}
191	     * @param b the second value, possibly {@code null}
192	     * @return whether the values are equal ignoring case
193	     */
194	    private boolean equalsIgnoreCase(String a, String b) {
195	        return a == null ? b == null : a.equalsIgnoreCase(b);
196	    }
