229	    /**
230	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
231	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
232	     * what gets stored and returned.
233	     *
234	     * @param telephone the raw telephone value from the request
235	     * @return the normalized E.164 telephone number
236	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
237	     */
238	    private String normalizeTelephone(String telephone) {
239	        String e164 = toE164(telephone);
240	        if (e164 == null) {
241	            throw new InvalidOwnerFieldsException(List.of("telephone"));
242	        }
243	        return e164;
244	    }
245	
246	    /**
247	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
248	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
249	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
250	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
251	     * it contains 8 to 15 digits after the {@code '+'}.
252	     *
253	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
254	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
255	     *
256	     * @param telephone the raw telephone value, possibly {@code null}
257	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
258	     */
259	    private String toE164(String telephone) {
260	        if (telephone == null) {
261	            return null;
262	        }
263	        String cleaned = telephone.replaceAll("[ \\-()]", "");
264	        String digits;
265	        if (cleaned.startsWith("+")) {
266	            digits = cleaned.substring(1);
267	        } else {
268	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
269	            digits = "61" + national;
270	        }
271	        if (!digits.matches("[0-9]{8,15}")) {
272	            return null;
273	        }
274	        return "+" + digits;
275	    }
276	
277	    /**
278	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
279	     * {@code null}. When present, the value must be a syntactically valid address; it is then stored
280	     * and returned lower-cased.
281	     *
282	     * @param email the raw email value from the request, possibly {@code null}
283	     * @return the lower-cased email, or {@code null} when none was supplied
284	     * @throws InvalidOwnerFieldsException if a value is present but not a valid email address
285	     */
286	    private String normalizeEmail(String email) {
287	        if (!StringUtils.hasText(email)) {
288	            return null;
289	        }
290	        String trimmed = email.trim();
291	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
292	            throw new InvalidOwnerFieldsException(List.of("email"));
293	        }
294	        return trimmed.toLowerCase(Locale.ROOT);
295	    }
296	
297	    /**
298	     * Rejects a telephone number whose E.164 form is already used by an existing owner. This enforces
299	     * that no two owners share the same E.164 telephone. Existing values are compared by their E.164
300	     * form; a stored value that cannot form a valid E.164 number is compared as-is.
301	     *
302	     * @param telephone the normalized (E.164) telephone of the owner being created
303	     * @throws DuplicateTelephoneException if another owner already has this E.164 telephone
304	     */
305	    private void requireUniqueTelephone(String telephone) {
306	        boolean inUse = this.clinicService.findAllOwners().stream()
307	            .map(Owner::getTelephone)
308	            .filter(existing -> existing != null)
309	            .map(existing -> {
310	                String e164 = toE164(existing);
311	                return e164 != null ? e164 : existing;
312	            })
313	            .anyMatch(telephone::equals);
314	        if (inUse) {
315	            throw new DuplicateTelephoneException(telephone);
316	        }
317	    }
318	
319	    /**
320	     * Rejects an owner whose last name and address match those of an existing owner, where both are
321	     * compared case-insensitively and with runs of whitespace collapsed to a single space (a shared
322	     * household). The caller skips this check when the request opts in via {@code sharesHousehold}.
323	     *
324	     * @param lastName the last name of the owner being created
325	     * @param address the address of the owner being created
326	     * @throws DuplicateHouseholdException if another owner shares the same last name and address
327	     */
328	    private void requireUniqueHousehold(String lastName, String address) {
329	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
330	            throw new DuplicateHouseholdException(lastName, address);
331	        }
332	    }
333	
334	    /**
335	     * Returns the existing owners that belong to the same household as the given last name and
336	     * address, i.e. those whose last name and address match case-insensitively and with runs of
337	     * whitespace collapsed to a single space.
338	     *
339	     * @param lastName the last name to match
340	     * @param address the address to match
341	     * @return the matching owners (possibly empty, never {@code null})
342	     */
343	    private List<Owner> findHouseholdMembers(String lastName, String address) {
344	        String normalizedLastName = normalizeForHousehold(lastName);
345	        String normalizedAddress = normalizeAddress(address);
346	        return this.clinicService.findAllOwners().stream()
347	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
348	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
349	            .toList();
350	    }
351	
352	    /**
353	     * Joins the owner being created to the shared household of any existing owner(s) that have the
354	     * same last name and address (compared case-insensitively with collapsed whitespace). Every
355	     * member of the household - the existing owners and the new one - is assigned the same stable
356	     * {@code householdId}, so the shared identifier can be read back from any of them.
357	     *
358	     * <p>When no existing owner shares the household there is nobody to share an identifier with, so
359	     * the owner is left without a {@code householdId}.
360	     *
361	     * @param owner the owner being created, whose {@code householdId} is set when a household is joined
362	     */
363	    private void joinHousehold(Owner owner) {
364	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
365	        if (members.isEmpty()) {
366	            return;
367	        }
368	        String householdId = computeHouseholdId(owner.getLastName(), owner.getAddress());
369	        owner.setHouseholdId(householdId);
370	        for (Owner member : members) {
371	            if (!householdId.equals(member.getHouseholdId())) {
372	                member.setHouseholdId(householdId);
373	                this.clinicService.saveOwner(member);
374	            }
375	        }
376	    }
377	
378	    /**
379	     * Computes the stable, shared household identifier for a last name and address. The value is
380	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last
381	     * name and address, so every owner in the same household computes the same identifier.
382	     *
383	     * @param lastName the last name of the household
384	     * @param address the address of the household
385	     * @return the household identifier, formatted {@code 'HH-<12 upper-case hex digits>'}
386	     */
387	    private String computeHouseholdId(String lastName, String address) {
388	        String key = normalizeForHousehold(lastName) + "\n" + normalizeAddress(address);
389	        try {
390	            byte[] digest = MessageDigest.getInstance("SHA-256")
391	                .digest(key.getBytes(StandardCharsets.UTF_8));
392	            StringBuilder hex = new StringBuilder();
393	            for (int i = 0; i < 6; i++) {
394	                hex.append(String.format("%02X", digest[i]));
395	            }
396	            return "HH-" + hex;
397	        } catch (NoSuchAlgorithmException e) {
398	            throw new IllegalStateException("SHA-256 algorithm not available", e);
399	        }
400	    }
401	
402	    /**
403	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
404	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
405	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
406	     *
407	     * @param value the raw value, possibly {@code null}
408	     * @return the normalized value
409	     */
410	    private String normalizeForHousehold(String value) {
411	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
412	    }
413	
414	    /**
415	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
416	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
417	     * value yields an empty string.
418	     *
419	     * @param value the raw value, possibly {@code null}
420	     * @return the trimmed, whitespace-collapsed value
421	     */
422	    private String collapseWhitespace(String value) {
423	        if (value == null) {
424	            return "";
425	        }
426	        return value.trim().replaceAll("\\s+", " ");
427	    }
428	
429	    /**
430	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
431	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
432	     * is upper-cased, and common street-type abbreviations are expanded as whole words
433	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
434	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
435	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
436	     *
437	     * @param address the raw address value, possibly {@code null}
438	     * @return the normalized address
439	     */
440	    private String normalizeAddress(String address) {
441	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
442	        if (collapsed.isEmpty()) {
443	            return "";
444	        }
445	        String[] tokens = collapsed.split(" ");
446	        StringBuilder normalized = new StringBuilder();
447	        for (int i = 0; i < tokens.length; i++) {
448	            if (i > 0) {
449	                normalized.append(' ');
450	            }
451	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
452	        }
453	        return normalized.toString();
454	    }
