458	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
459	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
460	        if (currentOwner == null) {
461	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
462	        }
463	        currentOwner.setAddress(ownerFieldsDto.getAddress());
464	        currentOwner.setCity(ownerFieldsDto.getCity());
465	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
466	        currentOwner.setLastName(ownerFieldsDto.getLastName());
467	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
468	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
469	        this.clinicService.saveOwner(currentOwner);
470	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
471	    }
